// Package benchutil provides test fixture helpers for CLI benchmarks.
//
// It creates realistic git repositories, transcripts, session states,
// and checkpoint data for benchmarking the hot paths (SaveStep, PostCommit/Condense).
package benchutil

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/redact"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// BenchRepo is a fully initialized git repository with Entire configured,
// ready for checkpoint benchmarks.
type BenchRepo struct {
	// Dir is the absolute path to the repository root.
	Dir string

	// Repo is the go-git repository handle.
	Repo *git.Repository

	// Store is the checkpoint GitStore for this repo.
	Store *checkpoint.GitStore

	// HeadHash is the current HEAD commit hash string.
	HeadHash string

	// WorktreeID is the worktree identifier (empty for main worktree).
	WorktreeID string

	// Strategy is the strategy name used in .entire/settings.json.
	Strategy string
}

// RepoOpts configures how NewBenchRepo creates the test repository.
type RepoOpts struct {
	// FileCount is the number of tracked files to create in the initial commit.
	// Each file is ~100 lines of Go code. Defaults to 10.
	FileCount int

	// FileSizeLines is the number of lines per file. Defaults to 100.
	FileSizeLines int

	// CommitCount is the number of commits to create. Defaults to 1.
	CommitCount int

	// Strategy is the strategy name for .entire/settings.json.
	// Defaults to "manual-commit".
	Strategy string

	// FeatureBranch, if non-empty, creates and checks out this branch
	// after the initial commits.
	FeatureBranch string
}

func (o *RepoOpts) withDefaults() RepoOpts {
	out := *o
	if out.FileCount == 0 {
		out.FileCount = 10
	}
	if out.FileSizeLines == 0 {
		out.FileSizeLines = 100
	}
	if out.CommitCount == 0 {
		out.CommitCount = 1
	}
	if out.Strategy == "" {
		out.Strategy = "manual-commit"
	}
	return out
}

// NewBenchRepo creates an isolated git repository for benchmarks.
// The repo has an initial commit with the configured number of files,
// a .gitignore excluding .entire/, and Entire settings initialized.
//
// Uses b.TempDir() so cleanup is automatic.
func NewBenchRepo(b *testing.B, opts RepoOpts) *BenchRepo {
	b.Helper()
	opts = opts.withDefaults()

	dir := b.TempDir()
	// Resolve symlinks (macOS /var -> /private/var)
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}

	// Init repo
	repo, err := git.PlainInit(dir, false)
	if err != nil {
		b.Fatalf("git init: %v", err)
	}

	// Create .gitignore and .entire settings
	writeFile(b, dir, ".gitignore", ".entire/\n")
	initEntireSettings(b, dir, opts.Strategy)

	// Generate initial files
	wt, err := repo.Worktree()
	if err != nil {
		b.Fatalf("worktree: %v", err)
	}

	for i := range opts.FileCount {
		name := fmt.Sprintf("src/file_%03d.go", i)
		content := GenerateGoFile(i, opts.FileSizeLines)
		writeFile(b, dir, name, content)
		if _, err := wt.Add(name); err != nil {
			b.Fatalf("add %s: %v", name, err)
		}
	}
	if _, err := wt.Add(".gitignore"); err != nil {
		b.Fatalf("add .gitignore: %v", err)
	}

	// Create commits
	var headHash plumbing.Hash
	for c := range opts.CommitCount {
		if c > 0 {
			// Modify a file for subsequent commits
			name := fmt.Sprintf("src/file_%03d.go", c%opts.FileCount)
			content := GenerateGoFile(c*1000, opts.FileSizeLines)
			writeFile(b, dir, name, content)
			if _, err := wt.Add(name); err != nil {
				b.Fatalf("add %s: %v", name, err)
			}
		}
		headHash, err = wt.Commit(fmt.Sprintf("Commit %d", c+1), &git.CommitOptions{
			Author: &object.Signature{
				Name:  "Bench User",
				Email: "bench@example.com",
				When:  time.Now(),
			},
		})
		if err != nil {
			b.Fatalf("commit %d: %v", c+1, err)
		}
	}

	// Optionally create feature branch
	if opts.FeatureBranch != "" {
		ref := plumbing.NewHashReference(
			plumbing.NewBranchReferenceName(opts.FeatureBranch), headHash)
		if err := repo.Storer.SetReference(ref); err != nil {
			b.Fatalf("create branch: %v", err)
		}
		// Checkout via git CLI (go-git v5 checkout bug)
		checkoutBranch(b, dir, opts.FeatureBranch)
	}

	br := &BenchRepo{
		Dir:      dir,
		Repo:     repo,
		Store:    checkpoint.NewGitStore(repo),
		HeadHash: headHash.String(),
		Strategy: opts.Strategy,
	}

	// Determine worktree ID
	wtID, err := paths.GetWorktreeID(dir)
	if err == nil {
		br.WorktreeID = wtID
	}

	return br
}

// WriteFile creates or overwrites a file relative to the repo root.
func (br *BenchRepo) WriteFile(b *testing.B, relPath, content string) {
	b.Helper()
	writeFile(b, br.Dir, relPath, content)
}

// AddAndCommit stages the given files and creates a commit.
// Returns the new HEAD hash.
func (br *BenchRepo) AddAndCommit(b *testing.B, message string, files ...string) string {
	b.Helper()
	wt, err := br.Repo.Worktree()
	if err != nil {
		b.Fatalf("worktree: %v", err)
	}
	for _, f := range files {
		if _, err := wt.Add(f); err != nil {
			b.Fatalf("add %s: %v", f, err)
		}
	}
	hash, err := wt.Commit(message, &git.CommitOptions{
		Author: &object.Signature{
			Name:  "Bench User",
			Email: "bench@example.com",
			When:  time.Now(),
		},
	})
	if err != nil {
		b.Fatalf("commit: %v", err)
	}
	br.HeadHash = hash.String()
	return hash.String()
}

// SessionOpts configures how CreateSessionState creates a session state file.

//go:build integration

package integration

import (
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

// TestOpenCodeHookFlow verifies the full hook flow for OpenCode:
// session-start → turn-start → file changes → turn-end → checkpoint → commit → condense → session-end.
func TestOpenCodeHookFlow(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t)
	env.InitEntireWithAgent(agent.AgentNameOpenCode)

	// Create OpenCode session
	session := env.NewOpenCodeSession()

	// 1. session-start
	if err := env.SimulateOpenCodeSessionStart(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("session-start error: %v", err)
	}

	// 2. turn-start (equivalent to UserPromptSubmit — captures pre-prompt state)
	if err := env.SimulateOpenCodeTurnStart(session.ID, session.TranscriptPath, "Add a feature"); err != nil {
		t.Fatalf("turn-start error: %v", err)
	}

	// 3. Agent makes file changes (AFTER turn-start so they're detected as new)
	env.WriteFile("feature.go", "package main\n// new feature")

	// 4. Create transcript with the file change
	session.CreateOpenCodeTranscript("Add a feature", []FileChange{
		{Path: "feature.go", Content: "package main\n// new feature"},
	})

	// 5. turn-end (equivalent to Stop — creates checkpoint)
	if err := env.SimulateOpenCodeTurnEnd(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("turn-end error: %v", err)
	}

	// 6. Verify checkpoint was created
	points := env.GetRewindPoints()
	if len(points) == 0 {
		t.Fatal("expected at least 1 rewind point after turn-end")
	}

	// 7. For manual-commit, user commits manually (triggers condensation).
	env.GitCommitWithShadowHooks("Add feature", "feature.go")

	// 8. session-end
	if err := env.SimulateOpenCodeSessionEnd(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("session-end error: %v", err)
	}

	// 9. Verify condensation happened (checkpoint on metadata branch)
	checkpointID := env.TryGetLatestCheckpointID()
	if checkpointID == "" {
		t.Fatal("expected checkpoint on metadata branch after commit")
	}

	// 10. Verify condensed data
	transcriptPath := SessionFilePath(checkpointID, paths.TranscriptFileName)
	_, found := env.ReadFileFromBranch(paths.MetadataBranchName, transcriptPath)
	if !found {
		t.Error("condensed transcript should exist on metadata branch")
	}
}

// TestOpenCodeAgentStrategyComposition verifies that the OpenCode agent and strategy
// work together correctly — agent parses session, strategy saves checkpoint, rewind works.
func TestOpenCodeAgentStrategyComposition(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t)
	env.InitEntireWithAgent(agent.AgentNameOpenCode)

	ag, err := agent.Get("opencode")
	if err != nil {
		t.Fatalf("Get(opencode) error = %v", err)
	}

	// Create session and transcript for agent interface testing.
	// The transcript references feature.go but the actual file doesn't need
	// to exist for ReadSession — it only parses the transcript JSONL.
	session := env.NewOpenCodeSession()
	transcriptPath := session.CreateOpenCodeTranscript("Add a feature", []FileChange{
		{Path: "feature.go", Content: "package main\n// new feature"},
	})

	// Read session via agent interface
	agentSession, err := ag.ReadSession(&agent.HookInput{
		SessionID:  session.ID,
		SessionRef: transcriptPath,
	})
	if err != nil {
		t.Fatalf("ReadSession() error = %v", err)
	}

	// Verify agent computed modified files
	if len(agentSession.ModifiedFiles) == 0 {
		t.Error("agent.ReadSession() should compute ModifiedFiles")
	}

	// Simulate session flow: session-start → turn-start → file changes → turn-end
	if err := env.SimulateOpenCodeSessionStart(session.ID, transcriptPath); err != nil {
		t.Fatalf("session-start error = %v", err)
	}
	if err := env.SimulateOpenCodeTurnStart(session.ID, transcriptPath, "Add a feature"); err != nil {
		t.Fatalf("turn-start error = %v", err)
	}

	// Create the actual file AFTER turn-start so the strategy detects it as new
	env.WriteFile("feature.go", "package main\n// new feature")

