// OpenCodeSession represents a simulated OpenCode session.
type OpenCodeSession struct {
	ID             string // Raw session ID (e.g., "opencode-session-1")
	TranscriptPath string
	env            *TestEnv
	msgCounter     int
	// messages accumulates all messages across turns, matching real `opencode export`
	// behavior where each export returns the full session history.
	messages []map[string]interface{}
}

// NewOpenCodeSession creates a new simulated OpenCode session.
func (env *TestEnv) NewOpenCodeSession() *OpenCodeSession {
	env.T.Helper()

	env.SessionCounter++
	sessionID := fmt.Sprintf("opencode-session-%d", env.SessionCounter)
	transcriptPath := filepath.Join(env.OpenCodeProjectDir, sessionID+".json")

	return &OpenCodeSession{
		ID:             sessionID,
		TranscriptPath: transcriptPath,
		env:            env,
	}
}

// CreateOpenCodeTranscript creates an OpenCode export JSON transcript file for the session.
// Each call appends new messages to the accumulated session history, matching real
// `opencode export` behavior where each export returns the full session history.
func (s *OpenCodeSession) CreateOpenCodeTranscript(prompt string, changes []FileChange) string {
	// User message
	s.msgCounter++
	s.messages = append(s.messages, map[string]interface{}{
		"info": map[string]interface{}{
			"id":   fmt.Sprintf("msg-%d", s.msgCounter),
			"role": "user",
			"time": map[string]interface{}{"created": 1708300000 + s.msgCounter},
		},
		"parts": []map[string]interface{}{
			{"type": "text", "text": prompt},
		},
	})

	// Assistant message with tool calls for file changes
	s.msgCounter++
	var parts []map[string]interface{}
	parts = append(parts, map[string]interface{}{
		"type": "text",
		"text": "I'll help you with that.",
	})
	for i, change := range changes {
		parts = append(parts, map[string]interface{}{
			"type":   "tool",
			"tool":   "write",
			"callID": fmt.Sprintf("call-%d", i+1),
			"state": map[string]interface{}{
				"status": "completed",
				"input":  map[string]string{"filePath": change.Path},
				"output": "File written: " + change.Path,
			},
		})
	}
	parts = append(parts, map[string]interface{}{
		"type": "text",
		"text": "Done!",
	})

	s.messages = append(s.messages, map[string]interface{}{
		"info": map[string]interface{}{
			"id":   fmt.Sprintf("msg-%d", s.msgCounter),
			"role": "assistant",
			"time": map[string]interface{}{
				"created":   1708300000 + s.msgCounter,
				"completed": 1708300000 + s.msgCounter + 5,
			},
			"tokens": map[string]interface{}{
				"input":     150,
				"output":    80,
				"reasoning": 10,
				"cache":     map[string]int{"read": 5, "write": 15},
			},
			"cost": 0.003,
		},
		"parts": parts,
	})

	// Build export session format with accumulated messages
	exportSession := map[string]interface{}{
		"info": map[string]interface{}{
			"id": s.ID,
		},
		"messages": s.messages,
	}

	// Ensure directory exists
	if err := os.MkdirAll(filepath.Dir(s.TranscriptPath), 0o755); err != nil {
		s.env.T.Fatalf("failed to create transcript dir: %v", err)
	}

	// Write export JSON transcript
	data, err := json.MarshalIndent(exportSession, "", "  ")
	if err != nil {
		s.env.T.Fatalf("failed to marshal transcript: %v", err)
	}
	if err := os.WriteFile(s.TranscriptPath, data, 0o644); err != nil {
		s.env.T.Fatalf("failed to write transcript: %v", err)
	}

	return s.TranscriptPath
}

// SessionOpts configures how CreateSessionState creates a session state file.
type SessionOpts struct {
	// SessionID is the session identifier. Auto-generated if empty.
	SessionID string

	// Phase is the session phase. Defaults to session.PhaseActive.
	Phase session.Phase

	// StepCount is the number of prior checkpoints. Defaults to 0.
	StepCount int

	// FilesTouched is the list of files tracked by this session.
	FilesTouched []string

	// TranscriptPath is the path to the live transcript file.
	TranscriptPath string

	// AgentType is the agent type. Defaults to agent.AgentTypeClaudeCode.
	AgentType types.AgentType
}

// CreateSessionState writes a session state file to .git/entire-sessions/.
// Returns the session ID used.
func (br *BenchRepo) CreateSessionState(b *testing.B, opts SessionOpts) string {
	b.Helper()

	if opts.SessionID == "" {
		cpID, err := id.Generate()
		if err != nil {
			b.Fatalf("generate session ID: %v", err)
		}
		opts.SessionID = fmt.Sprintf("bench-%s", cpID)
	}
	if opts.Phase == "" {
		opts.Phase = session.PhaseActive
	}

	if opts.AgentType == "" {
		opts.AgentType = agent.AgentTypeClaudeCode
	}

	now := time.Now()
	state := &session.State{
		SessionID:      opts.SessionID,
		BaseCommit:     br.HeadHash,
		WorktreePath:   br.Dir,
		WorktreeID:     br.WorktreeID,
		StartedAt:      now,
		Phase:          opts.Phase,
		StepCount:      opts.StepCount,
		FilesTouched:   opts.FilesTouched,
		TranscriptPath: opts.TranscriptPath,
		AgentType:      opts.AgentType,
	}

	// Write to .git/entire-sessions/<session-id>.json
	gitDir := filepath.Join(br.Dir, ".git")
	sessDir := filepath.Join(gitDir, session.SessionStateDirName)
	if err := os.MkdirAll(sessDir, 0o750); err != nil {
		b.Fatalf("mkdir sessions: %v", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
	if err != nil {
		b.Fatalf("marshal state: %v", err)
	}

	statePath := filepath.Join(sessDir, opts.SessionID+".json")
	if err := os.WriteFile(statePath, data, 0o600); err != nil {
		b.Fatalf("write state: %v", err)
	}

	return opts.SessionID
}

// TranscriptOpts configures how GenerateTranscript creates JSONL data.
type TranscriptOpts struct {
	// MessageCount is the number of JSONL messages to generate.
	MessageCount int

	// AvgMessageBytes is the approximate size of each message's content field.
	// Defaults to 500.
	AvgMessageBytes int

	// IncludeToolUse adds realistic tool_use messages (file edits, bash commands).
	IncludeToolUse bool

	// FilesTouched is the list of files to reference in tool_use messages.
	// Only used when IncludeToolUse is true.
	FilesTouched []string
}

// GenerateTranscript creates realistic Claude Code JSONL transcript data.
// Returns the raw bytes suitable for writing to full.jsonl.
func GenerateTranscript(opts TranscriptOpts) []byte {
	if opts.AvgMessageBytes == 0 {
		opts.AvgMessageBytes = 500
	}

	var buf strings.Builder
	for i := range opts.MessageCount {
		msg := generateTranscriptMessage(i, opts)
		data, err := json.Marshal(msg)
		if err != nil {
			// Should never happen with map[string]any, but satisfy errcheck
			continue
		}
		buf.Write(data)
		buf.WriteByte('\n')
	}
	return []byte(buf.String())
}

// WriteTranscriptFile writes transcript data to a file and returns the path.
func (br *BenchRepo) WriteTranscriptFile(b *testing.B, sessionID string, data []byte) string {
	b.Helper()
	// Write to .entire/metadata/<session-id>/full.jsonl (matching real layout)
	relDir := filepath.Join(".entire", "metadata", sessionID)
	relPath := filepath.Join(relDir, "full.jsonl")
	absDir := filepath.Join(br.Dir, relDir)

